-- PricePulse V279: 40 top stores + one round icon each (logos/store-icons/<file>.png).
-- Safe to run more than once. Existing stores keep their slug, domain and active flag; only the logo changes.
-- New stores are added as ACTIVE (they show only where a product has a listing on that store).
-- Brand shops (OnePlus, Dell, boAt ...) are STORES here; the BRANDS table is not touched.

-- 1) logo for stores that already exist (matched by name or domain)
update public.pp_catalog_stores set logo_url='logos/store-icons/amazon.png' where lower(name)=lower('Amazon') or lower(replace(replace(coalesce(domain,''),'https://',''),'www.',''))='amazon.in';
